-- PNG-11 (docs/decisions.md Q-38): starter templates per industry (ค้าปลีก, โรงพยาบาล, การเงิน/ประกัน,
-- โรงแรม, การศึกษา, ภาครัฐ), DRAFT sample text pending legal review -- the same move PNG-03 (Q-14)
-- already made for data-subject groups. platform.templates/notice.wizard_templates already carry an
-- `industry` column from the very first baseline migration (00002_platform.sql, 00007_notice.sql),
-- unused until now -- no schema change, only seed data.
ALTER TABLE platform.templates NO FORCE ROW LEVEL SECURITY;
ALTER TABLE notice.wizard_templates NO FORCE ROW LEVEL SECURITY;

