    INSERT INTO platform.templates (tenant_id, template_type, code, name, language, industry, content, status)
    VALUES
        (NULL, 'notice_wizard', 'retail', 'ค้าปลีก', 'th', 'retail', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "[ร่าง — ข้อความตัวอย่างนี้ต้องได้รับการทบทวนและอนุมัติจากฝ่ายกฎหมาย/DPO ก่อนเผยแพร่จริง]"}]}, {"type": "heading", "attrs": {"level": 2.0, "topic": "purpose_basis"}, "content": [{"type": "text", "text": "วัตถุประสงค์และฐานทางกฎหมายในการเก็บรวบรวม ใช้ หรือเปิดเผยข้อมูล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "เราเก็บรวบรวม ใช้ และเปิดเผยข้อมูลส่วนบุคคลของท่านในฐานะลูกค้าหรือผู้ใช้บริการร้านค้า/แพลตฟอร์มค้าปลีกของเราเพื่อวัตถุประสงค์ [โปรดระบุวัตถุประสงค์] ภายใต้ฐานทางกฎหมาย [โปรดระบุฐานทางกฎหมายตามมาตรา 24 หรือ 26]"}]}, {"type": "heading", "attrs": {"level": 2.0, "topic": "consequence"}, "content": [{"type": "text", "text": "ผลกระทบหากไม่ให้ข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "[โปรดระบุผลกระทบหากท่านไม่ให้ข้อมูลที่จำเป็นตามกฎหมายหรือสัญญา]"}]}, {"type": "heading", "attrs": {"level": 2.0, "topic": "data"}, "content": [{"type": "text", "text": "ข้อมูลส่วนบุคคลที่เก็บรวบรวม"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "[โปรดระบุประเภทข้อมูลส่วนบุคคลของท่านในฐานะลูกค้าหรือผู้ใช้บริการร้านค้า/แพลตฟอร์มค้าปลีกของเราที่เก็บรวบรวม]"}]}, {"type": "heading", "attrs": {"level": 2.0, "topic": "retention"}, "content": [{"type": "text", "text": "ระยะเวลาการเก็บรักษาข้อมูล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "[โปรดระบุระยะเวลาการเก็บรักษาข้อมูล]"}]}, {"type": "heading", "attrs": {"level": 2.0, "topic": "recipients"}, "content": [{"type": "text", "text": "ผู้รับข้อมูลและการโอนข้อมูลไปต่างประเทศ"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "[โปรดระบุผู้รับข้อมูล หากมีการโอนข้อมูลไปต่างประเทศ โปรดระบุประเทศปลายทางและฐานการโอน]"}]}, {"type": "heading", "attrs": {"level": 2.0, "topic": "contact"}, "content": [{"type": "text", "text": "ข้อมูลติดต่อผู้ควบคุมข้อมูลส่วนบุคคลและเจ้าหน้าที่คุ้มครองข้อมูลส่วนบุคคล (DPO)"}]}, {"type": "paragraph", "content": [{"type": "mergeField", "attrs": {"key": "org_name_th"}}, {"type": "text", "text": " อีเมล "}, {"type": "mergeField", "attrs": {"key": "org_email"}}, {"type": "text", "text": " โทร "}, {"type": "mergeField", "attrs": {"key": "org_phone"}}, {"type": "text", "text": " ที่อยู่ "}, {"type": "mergeField", "attrs": {"key": "org_address"}}]}, {"type": "heading", "attrs": {"level": 2.0, "topic": "rights"}, "content": [{"type": "text", "text": "สิทธิของเจ้าของข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ท่านมีสิทธิขอเข้าถึง ขอสำเนา ขอแก้ไข ขอให้โอนย้าย ขอให้ระงับการใช้ ขอให้ลบหรือทำลาย และคัดค้านการประมวลผลข้อมูลส่วนบุคคลของท่าน รวมถึงสิทธิขอถอนความยินยอม ตามที่กฎหมายคุ้มครองข้อมูลส่วนบุคคลกำหนด"}]}]}'::jsonb, 'published'),
